-- UTF-8. Verified statutory parameters; company standard days copied from TB_KYCONG.
-- No employee identities or membership/residency assumptions. No historical payroll updates.
WHENEVER SQLERROR EXIT FAILURE ROLLBACK
WHENEVER OSERROR EXIT FAILURE ROLLBACK
SET DEFINE OFF
SET SERVEROUTPUT ON
DECLARE
 n NUMBER; pid NUMBER;
BEGIN
 IF USER <> 'HR' THEN RAISE_APPLICATION_ERROR(-20090,'Expected HR schema'); END IF;
 SELECT COUNT(*) INTO n FROM TB_CHINH_SACH_LUONG WHERE MA_CHINH_SACH NOT LIKE 'CALENDAR_2026_%' AND TRANG_THAI='ACTIVE' AND NGAY_HIEU_LUC<=DATE '2026-12-31' AND NVL(NGAY_HET_HIEU_LUC,DATE '9999-12-31')>=DATE '2026-01-01';
 IF n>0 THEN RAISE_APPLICATION_ERROR(-20091,'Existing salary policy requires reconciliation'); END IF;
 FOR k IN (SELECT MAKYCONG,NAM,THANG,NGAYCONGTRONGTHANG FROM TB_KYCONG WHERE NAM=2026 AND DELETED_DATE IS NULL) LOOP
  IF k.NGAYCONGTRONGTHANG IS NULL OR k.NGAYCONGTRONGTHANG<=0 THEN RAISE_APPLICATION_ERROR(-20092,'Invalid period standard days'); END IF;
  SELECT COUNT(*) INTO n FROM TB_CHINH_SACH_LUONG WHERE MA_CHINH_SACH='CALENDAR_'||k.MAKYCONG;
  IF n=0 THEN
   INSERT INTO TB_CHINH_SACH_LUONG (ID,MA_CHINH_SACH,TEN_CHINH_SACH,NGAY_HIEU_LUC,NGAY_HET_HIEU_LUC,SO_CONG_CHUAN_THANG,SO_GIO_CHUAN_NGAY,HE_SO_LAM_DEM,TRANG_THAI)
   VALUES (SEQ_CHINH_SACH_LUONG.NEXTVAL,'CALENDAR_'||k.MAKYCONG,N'Công chuẩn từ kỳ công; 8 giờ/ngày; phụ trội đêm 30% (BLLĐ Điều 98)',TO_DATE(k.MAKYCONG||'01','YYYYMMDD'),LAST_DAY(TO_DATE(k.MAKYCONG||'01','YYYYMMDD')),k.NGAYCONGTRONGTHANG,8,0.30,'ACTIVE');
  END IF;
 END LOOP;
 SELECT COUNT(*) INTO n FROM TB_CHINH_SACH_BHXH WHERE MA_CHINH_SACH='VN_BH_2026_H1';
 IF n=0 THEN
  SELECT COUNT(*) INTO n FROM TB_CHINH_SACH_BHXH WHERE TRANG_THAI='ACTIVE' AND NGAY_HIEU_LUC<=DATE '2026-06-30' AND NVL(NGAY_HET_HIEU_LUC,DATE '9999-12-31')>=DATE '2026-01-01';
  IF n>0 THEN RAISE_APPLICATION_ERROR(-20091,'Existing insurance policy overlaps'); END IF;
  INSERT INTO TB_CHINH_SACH_BHXH (ID,MA_CHINH_SACH,TEN_CHINH_SACH,NGAY_HIEU_LUC,NGAY_HET_HIEU_LUC,MUC_THAM_CHIEU,TY_LE_BHXH_NLD,TY_LE_BHYT_NLD,TY_LE_BHTN_NLD,TY_LE_BHXH_NSDLD,TY_LE_BHYT_NSDLD,TY_LE_BHTN_NSDLD,TY_LE_TNLD_BNN_NSDLD,TY_LE_TNLD_BNN_UU_DAI,AP_DUNG_TRAN_BHXH_BHYT,AP_DUNG_TRAN_BHTN,TRANG_THAI)
  VALUES (SEQ_CHINH_SACH_BHXH.NEXTVAL,'VN_BH_2026_H1',N'Luật BHXH 41/2024; NĐ 188/2025, 374/2025; mức tham chiếu 73/2024 và 161/2026',DATE '2026-01-01',DATE '2026-06-30',2340000,.08,.015,.01,.17,.03,.01,.005,.003,1,1,'ACTIVE');
 END IF;
 SELECT ID INTO pid FROM TB_CHINH_SACH_BHXH WHERE MA_CHINH_SACH='VN_BH_2026_H1';
 SELECT COUNT(*) INTO n FROM TB_CHINH_SACH_BHXH_VUNG WHERE POLICY_BHXH_ID=pid AND VUNG_LUONG=1;
 IF n=0 THEN INSERT INTO TB_CHINH_SACH_BHXH_VUNG (ID,POLICY_BHXH_ID,VUNG_LUONG,LUONG_TOI_THIEU_THANG,LUONG_TOI_THIEU_GIO,HE_SO_SAN_DOANH_NGHIEP) VALUES(SEQ_CHINH_SACH_BHXH_VUNG.NEXTVAL,pid,1,5310000,25500,1); END IF;
 SELECT COUNT(*) INTO n FROM TB_CHINH_SACH_BHXH_VUNG WHERE POLICY_BHXH_ID=pid AND VUNG_LUONG=2;
 IF n=0 THEN INSERT INTO TB_CHINH_SACH_BHXH_VUNG (ID,POLICY_BHXH_ID,VUNG_LUONG,LUONG_TOI_THIEU_THANG,LUONG_TOI_THIEU_GIO,HE_SO_SAN_DOANH_NGHIEP) VALUES(SEQ_CHINH_SACH_BHXH_VUNG.NEXTVAL,pid,2,4730000,22700,1); END IF;
 SELECT COUNT(*) INTO n FROM TB_CHINH_SACH_BHXH_VUNG WHERE POLICY_BHXH_ID=pid AND VUNG_LUONG=3;
 IF n=0 THEN INSERT INTO TB_CHINH_SACH_BHXH_VUNG (ID,POLICY_BHXH_ID,VUNG_LUONG,LUONG_TOI_THIEU_THANG,LUONG_TOI_THIEU_GIO,HE_SO_SAN_DOANH_NGHIEP) VALUES(SEQ_CHINH_SACH_BHXH_VUNG.NEXTVAL,pid,3,4140000,20000,1); END IF;
 SELECT COUNT(*) INTO n FROM TB_CHINH_SACH_BHXH_VUNG WHERE POLICY_BHXH_ID=pid AND VUNG_LUONG=4;
 IF n=0 THEN INSERT INTO TB_CHINH_SACH_BHXH_VUNG (ID,POLICY_BHXH_ID,VUNG_LUONG,LUONG_TOI_THIEU_THANG,LUONG_TOI_THIEU_GIO,HE_SO_SAN_DOANH_NGHIEP) VALUES(SEQ_CHINH_SACH_BHXH_VUNG.NEXTVAL,pid,4,3700000,17800,1); END IF;
 SELECT COUNT(*) INTO n FROM TB_CHINH_SACH_BHXH WHERE MA_CHINH_SACH='VN_BH_2026_H2';
 IF n=0 THEN
  SELECT COUNT(*) INTO n FROM TB_CHINH_SACH_BHXH WHERE TRANG_THAI='ACTIVE' AND NGAY_HIEU_LUC<=DATE '2026-12-31' AND NVL(NGAY_HET_HIEU_LUC,DATE '9999-12-31')>=DATE '2026-07-01';
  IF n>0 THEN RAISE_APPLICATION_ERROR(-20091,'Existing insurance policy overlaps'); END IF;
  INSERT INTO TB_CHINH_SACH_BHXH (ID,MA_CHINH_SACH,TEN_CHINH_SACH,NGAY_HIEU_LUC,NGAY_HET_HIEU_LUC,MUC_THAM_CHIEU,TY_LE_BHXH_NLD,TY_LE_BHYT_NLD,TY_LE_BHTN_NLD,TY_LE_BHXH_NSDLD,TY_LE_BHYT_NSDLD,TY_LE_BHTN_NSDLD,TY_LE_TNLD_BNN_NSDLD,TY_LE_TNLD_BNN_UU_DAI,AP_DUNG_TRAN_BHXH_BHYT,AP_DUNG_TRAN_BHTN,TRANG_THAI)
  VALUES (SEQ_CHINH_SACH_BHXH.NEXTVAL,'VN_BH_2026_H2',N'Luật BHXH 41/2024; NĐ 188/2025, 374/2025; mức tham chiếu 73/2024 và 161/2026',DATE '2026-07-01',DATE '2026-12-31',2530000,.08,.015,.01,.17,.03,.01,.005,.003,1,1,'ACTIVE');
 END IF;
 SELECT ID INTO pid FROM TB_CHINH_SACH_BHXH WHERE MA_CHINH_SACH='VN_BH_2026_H2';
 SELECT COUNT(*) INTO n FROM TB_CHINH_SACH_BHXH_VUNG WHERE POLICY_BHXH_ID=pid AND VUNG_LUONG=1;
 IF n=0 THEN INSERT INTO TB_CHINH_SACH_BHXH_VUNG (ID,POLICY_BHXH_ID,VUNG_LUONG,LUONG_TOI_THIEU_THANG,LUONG_TOI_THIEU_GIO,HE_SO_SAN_DOANH_NGHIEP) VALUES(SEQ_CHINH_SACH_BHXH_VUNG.NEXTVAL,pid,1,5310000,25500,1); END IF;
 SELECT COUNT(*) INTO n FROM TB_CHINH_SACH_BHXH_VUNG WHERE POLICY_BHXH_ID=pid AND VUNG_LUONG=2;
 IF n=0 THEN INSERT INTO TB_CHINH_SACH_BHXH_VUNG (ID,POLICY_BHXH_ID,VUNG_LUONG,LUONG_TOI_THIEU_THANG,LUONG_TOI_THIEU_GIO,HE_SO_SAN_DOANH_NGHIEP) VALUES(SEQ_CHINH_SACH_BHXH_VUNG.NEXTVAL,pid,2,4730000,22700,1); END IF;
 SELECT COUNT(*) INTO n FROM TB_CHINH_SACH_BHXH_VUNG WHERE POLICY_BHXH_ID=pid AND VUNG_LUONG=3;
 IF n=0 THEN INSERT INTO TB_CHINH_SACH_BHXH_VUNG (ID,POLICY_BHXH_ID,VUNG_LUONG,LUONG_TOI_THIEU_THANG,LUONG_TOI_THIEU_GIO,HE_SO_SAN_DOANH_NGHIEP) VALUES(SEQ_CHINH_SACH_BHXH_VUNG.NEXTVAL,pid,3,4140000,20000,1); END IF;
 SELECT COUNT(*) INTO n FROM TB_CHINH_SACH_BHXH_VUNG WHERE POLICY_BHXH_ID=pid AND VUNG_LUONG=4;
 IF n=0 THEN INSERT INTO TB_CHINH_SACH_BHXH_VUNG (ID,POLICY_BHXH_ID,VUNG_LUONG,LUONG_TOI_THIEU_THANG,LUONG_TOI_THIEU_GIO,HE_SO_SAN_DOANH_NGHIEP) VALUES(SEQ_CHINH_SACH_BHXH_VUNG.NEXTVAL,pid,4,3700000,17800,1); END IF;
 SELECT COUNT(*) INTO n FROM TB_CHINH_SACH_CONG_DOAN WHERE MA_CHINH_SACH='VN_CD_PRIVATE_2026';
 IF n=0 THEN
  SELECT COUNT(*) INTO n FROM TB_CHINH_SACH_CONG_DOAN WHERE TRANG_THAI='ACTIVE' AND NGAY_HIEU_LUC<=DATE '2026-12-31' AND NVL(NGAY_HET_HIEU_LUC,DATE '9999-12-31')>=DATE '2026-01-01';
  IF n>0 THEN RAISE_APPLICATION_ERROR(-20091,'Existing union policy overlaps'); END IF;
  INSERT INTO TB_CHINH_SACH_CONG_DOAN (ID,MA_CHINH_SACH,TEN_CHINH_SACH,NGAY_HIEU_LUC,NGAY_HET_HIEU_LUC,TY_LE_DOAN_PHI_NLD,CAP_PERCENT_STATUTORY_BASE_SALARY,KINH_PHI_CONG_DOAN_NSDLD,TRANG_THAI)
  VALUES (SEQ_CHINH_SACH_CONG_DOAN.NEXTVAL,'VN_CD_PRIVATE_2026',N'Doanh nghiệp ngoài nhà nước; QĐ 61/QĐ-TLĐ; Luật Công đoàn 50/2024 Điều 29',DATE '2026-01-01',DATE '2026-12-31',.005,.10,.02,'ACTIVE');
 END IF;
 SELECT COUNT(*) INTO n FROM TB_THUE_TNCN_CHINH_SACH WHERE MA_CHINH_SACH='VN_PIT_2026';
 IF n=0 THEN
  SELECT COUNT(*) INTO n FROM TB_THUE_TNCN_CHINH_SACH WHERE TAX_YEAR=2026 AND TRANG_THAI='ACTIVE';
  IF n>0 THEN RAISE_APPLICATION_ERROR(-20091,'Existing tax policy requires reconciliation'); END IF;
  INSERT INTO TB_THUE_TNCN_CHINH_SACH (ID,MA_CHINH_SACH,TEN_CHINH_SACH,TAX_YEAR,NGAY_HIEU_LUC,NGAY_HET_HIEU_LUC,GIAM_TRU_BAN_THAN_THANG,GIAM_TRU_PHU_THUOC_THANG,GIAM_TRU_BAN_THAN_NAM,GIAM_TRU_PHU_THUOC_NAM,TRANG_THAI)
  VALUES (SEQ_THUE_TNCN_CHINH_SACH.NEXTVAL,'VN_PIT_2026',N'Luật 109/2025/QH15; giảm trừ 15,5 triệu và 6,2 triệu; biểu thuế 5 bậc',2026,DATE '2026-01-01',DATE '2026-12-31',15500000,6200000,186000000,74400000,'ACTIVE');
 END IF;
 SELECT ID INTO pid FROM TB_THUE_TNCN_CHINH_SACH WHERE MA_CHINH_SACH='VN_PIT_2026';
 SELECT COUNT(*) INTO n FROM TB_THUE_TNCN_BAC WHERE POLICY_THUE_ID=pid AND PERIOD_TYPE='MONTH' AND BAC_THUE=1;
 IF n=0 THEN INSERT INTO TB_THUE_TNCN_BAC (ID,POLICY_THUE_ID,TAX_YEAR,PERIOD_TYPE,BAC_THUE,CAN_DUOI,CAN_TREN,THUE_SUAT) VALUES (SEQ_THUE_TNCN_BAC.NEXTVAL,pid,2026,'MONTH',1,0,10000000,0.05); END IF;
 SELECT COUNT(*) INTO n FROM TB_THUE_TNCN_BAC WHERE POLICY_THUE_ID=pid AND PERIOD_TYPE='MONTH' AND BAC_THUE=2;
 IF n=0 THEN INSERT INTO TB_THUE_TNCN_BAC (ID,POLICY_THUE_ID,TAX_YEAR,PERIOD_TYPE,BAC_THUE,CAN_DUOI,CAN_TREN,THUE_SUAT) VALUES (SEQ_THUE_TNCN_BAC.NEXTVAL,pid,2026,'MONTH',2,10000000,30000000,0.1); END IF;
 SELECT COUNT(*) INTO n FROM TB_THUE_TNCN_BAC WHERE POLICY_THUE_ID=pid AND PERIOD_TYPE='MONTH' AND BAC_THUE=3;
 IF n=0 THEN INSERT INTO TB_THUE_TNCN_BAC (ID,POLICY_THUE_ID,TAX_YEAR,PERIOD_TYPE,BAC_THUE,CAN_DUOI,CAN_TREN,THUE_SUAT) VALUES (SEQ_THUE_TNCN_BAC.NEXTVAL,pid,2026,'MONTH',3,30000000,60000000,0.2); END IF;
 SELECT COUNT(*) INTO n FROM TB_THUE_TNCN_BAC WHERE POLICY_THUE_ID=pid AND PERIOD_TYPE='MONTH' AND BAC_THUE=4;
 IF n=0 THEN INSERT INTO TB_THUE_TNCN_BAC (ID,POLICY_THUE_ID,TAX_YEAR,PERIOD_TYPE,BAC_THUE,CAN_DUOI,CAN_TREN,THUE_SUAT) VALUES (SEQ_THUE_TNCN_BAC.NEXTVAL,pid,2026,'MONTH',4,60000000,100000000,0.3); END IF;
 SELECT COUNT(*) INTO n FROM TB_THUE_TNCN_BAC WHERE POLICY_THUE_ID=pid AND PERIOD_TYPE='MONTH' AND BAC_THUE=5;
 IF n=0 THEN INSERT INTO TB_THUE_TNCN_BAC (ID,POLICY_THUE_ID,TAX_YEAR,PERIOD_TYPE,BAC_THUE,CAN_DUOI,CAN_TREN,THUE_SUAT) VALUES (SEQ_THUE_TNCN_BAC.NEXTVAL,pid,2026,'MONTH',5,100000000,NULL,0.35); END IF;
 SELECT COUNT(*) INTO n FROM TB_THUE_TNCN_BAC WHERE POLICY_THUE_ID=pid AND PERIOD_TYPE='YEAR' AND BAC_THUE=1;
 IF n=0 THEN INSERT INTO TB_THUE_TNCN_BAC (ID,POLICY_THUE_ID,TAX_YEAR,PERIOD_TYPE,BAC_THUE,CAN_DUOI,CAN_TREN,THUE_SUAT) VALUES (SEQ_THUE_TNCN_BAC.NEXTVAL,pid,2026,'YEAR',1,0,120000000,0.05); END IF;
 SELECT COUNT(*) INTO n FROM TB_THUE_TNCN_BAC WHERE POLICY_THUE_ID=pid AND PERIOD_TYPE='YEAR' AND BAC_THUE=2;
 IF n=0 THEN INSERT INTO TB_THUE_TNCN_BAC (ID,POLICY_THUE_ID,TAX_YEAR,PERIOD_TYPE,BAC_THUE,CAN_DUOI,CAN_TREN,THUE_SUAT) VALUES (SEQ_THUE_TNCN_BAC.NEXTVAL,pid,2026,'YEAR',2,120000000,360000000,0.1); END IF;
 SELECT COUNT(*) INTO n FROM TB_THUE_TNCN_BAC WHERE POLICY_THUE_ID=pid AND PERIOD_TYPE='YEAR' AND BAC_THUE=3;
 IF n=0 THEN INSERT INTO TB_THUE_TNCN_BAC (ID,POLICY_THUE_ID,TAX_YEAR,PERIOD_TYPE,BAC_THUE,CAN_DUOI,CAN_TREN,THUE_SUAT) VALUES (SEQ_THUE_TNCN_BAC.NEXTVAL,pid,2026,'YEAR',3,360000000,720000000,0.2); END IF;
 SELECT COUNT(*) INTO n FROM TB_THUE_TNCN_BAC WHERE POLICY_THUE_ID=pid AND PERIOD_TYPE='YEAR' AND BAC_THUE=4;
 IF n=0 THEN INSERT INTO TB_THUE_TNCN_BAC (ID,POLICY_THUE_ID,TAX_YEAR,PERIOD_TYPE,BAC_THUE,CAN_DUOI,CAN_TREN,THUE_SUAT) VALUES (SEQ_THUE_TNCN_BAC.NEXTVAL,pid,2026,'YEAR',4,720000000,1200000000,0.3); END IF;
 SELECT COUNT(*) INTO n FROM TB_THUE_TNCN_BAC WHERE POLICY_THUE_ID=pid AND PERIOD_TYPE='YEAR' AND BAC_THUE=5;
 IF n=0 THEN INSERT INTO TB_THUE_TNCN_BAC (ID,POLICY_THUE_ID,TAX_YEAR,PERIOD_TYPE,BAC_THUE,CAN_DUOI,CAN_TREN,THUE_SUAT) VALUES (SEQ_THUE_TNCN_BAC.NEXTVAL,pid,2026,'YEAR',5,1200000000,NULL,0.35); END IF;
 DBMS_OUTPUT.PUT_LINE('Policy seed completed. No employee profiles fabricated.');
END;
/
COMMIT;
